// Validate incoming data
const items = $input.all();
const validatedItems = [];

for (const item of items) {
  const data = item.json.body

  // Validate required fields
  if (!data.leadName || !data.businessName || !data.websiteUrl || !data.email || !data.phoneNumber) {
    throw new Error('Missing required fields');
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(data.email)) {
    throw new Error('Invalid email format');
  }

  // Format website URL
  let websiteUrl = data.websiteUrl;
  if (!websiteUrl.startsWith('http://') && !websiteUrl.startsWith('https://')) {
    websiteUrl = 'https://' + websiteUrl;
  }

  // Validate URL format


  validatedItems.push({
    json: {
      ...data,
      websiteUrl,
      processedAt: new Date().toISOString(),
      workflowId: $execution.id
    }
  });
}

return validatedItems;

const items = $input.all();
const processedItems = [];

for (const item of items) {
  const websiteData = item.json;
  const originalData = $node["Validate & Format Data"].json;

  let scrapingSuccessful = false;
  let extractedContent = {};

  if (websiteData.error) {
    // Scraping failed
    scrapingSuccessful = false;
  } else {
    // Extract content from HTML
    const html = websiteData.data || '';

    // Simple extraction patterns
    const titleMatch = html.match(/<title>([^<]+)<\/title>/i);
    const metaDescMatch = html.match(/<meta\s+name=["']description["']\s+content=["']([^"']+)["']/i);

    // Extract text content (remove scripts and styles)
    let textContent = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Look for common patterns
    const aboutMatches = textContent.match(/about\s+us[\s\S]{0,500}/i);
    const servicesMatches = textContent.match(/services?[\s\S]{0,500}/i);
    const faqMatches = textContent.match(/faq|frequently\s+asked[\s\S]{0,1000}/i);

    extractedContent = {
      title: titleMatch ? titleMatch[1] : originalData.businessName,
      description: metaDescMatch ? metaDescMatch[1] : '',
      aboutText: aboutMatches ? aboutMatches[0].substring(0, 300) : '',
      servicesText: servicesMatches ? servicesMatches[0].substring(0, 300) : '',
      faqText: faqMatches ? faqMatches[0].substring(0, 500) : '',
      rawTextSample: textContent.substring(0, 1000)
    };

    scrapingSuccessful = Object.values(extractedContent).some(v => v && v.length > 50);
  }

  processedItems.push({
    json: {
      ...originalData,
      scrapingSuccessful,
      extractedContent,
      kbCreationStatus: scrapingSuccessful ? 'pending_website_data' : 'pending_generic_data'
    }
  });
}

return processedItems;

// Create KB from scraped data
const items = $input.all();
const kbItems = [];

for (const item of items) {
  const data = item.json;
  const content = data.extractedContent;

  let knowledgeBase = `# ${data.businessName} AI Assistant Knowledge Base\n\n`;
  knowledgeBase += `## Business Information\n`;
  knowledgeBase += `- Business Name: ${data.businessName}\n`;
  knowledgeBase += `- Contact Person: ${data.leadName}\n`;
  knowledgeBase += `- Website: ${data.websiteUrl}\n\n`;

  if (content.title) {
    knowledgeBase += `## About ${content.title}\n`;
  }

  if (content.description) {
    knowledgeBase += `${content.description}\n\n`;
  }

  if (content.aboutText) {
    knowledgeBase += `## About Us\n${content.aboutText}\n\n`;
  }

  if (content.servicesText) {
    knowledgeBase += `## Services\n${content.servicesText}\n\n`;
  }

  if (content.faqText) {
    knowledgeBase += `## Frequently Asked Questions\n${content.faqText}\n\n`;
  }

  // Add AI assistant context
  knowledgeBase += `## AI Assistant Instructions\n`;
  knowledgeBase += `You are an AI assistant for ${data.businessName}. `;
  knowledgeBase += `You're speaking with ${data.leadName} to demonstrate how AI can help their business. `;
  knowledgeBase += `Be helpful, professional, and showcase your knowledge about their business based on the information above. `;
  knowledgeBase += `If asked about something not in your knowledge base, politely explain that you're a demo assistant `;
  knowledgeBase += `and suggest they could have a fully customized AI with complete business knowledge.\n`;

  kbItems.push({
    json: {
      ...data,
      knowledgeBase,
      kbCreationStatus: 'success_website_data'
    }
  });
}

return kbItems;

