function escape(str) {
  if (typeof str !== "string") {
    try {
      str = JSON.stringify(str);
    } catch (e) {
      str = String(str || "");
    }
  }
  return str
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '')
    .replace(/\t/g, '\\t');
}

